css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .instrucciones-box{border: 2px solid var(--bosque); border-radius: 12px; padding: 10px 12px; margin-bottom: 10px; width: 100%;}
.mz .necesitas{font-family: sans-serif; font-size: 11px; font-weight: 700; background: #f0f0f0; border: 1px solid #ccc; border-radius: 5px; padding: 3px 8px; display: inline-block; margin-bottom: 7px;}
.mz .pasos-lista{display: flex; flex-direction: column; gap: 4px;}
.mz .paso-item{display: flex; gap: 8px; font-size: 15px; font-weight: 600; line-height: 1.4;}
.mz .paso-num{font-family: sans-serif; font-weight: 700; flex-shrink: 0; min-width: 16px;}
.mz .preguntas-lista{display: flex; flex-direction: column; gap: 7px; margin-bottom: 10px;}
.mz .pregunta-item{display: flex; flex-direction: column; gap: 2px;}
.mz .pregunta-texto{font-size: 15px; font-weight: 700;}
.mz .respuesta-linea{border-bottom: 1.5px solid var(--bosque); height: 20px; width: 100%;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px;}
.mz .vf-item{display: flex; align-items: center; justify-content: space-between; gap: 12px;}
.mz .vf-texto{font-size: 15px; font-weight: 600; flex: 1; line-height: 1.3;}
.mz .vf-opciones{display: flex; gap: 5px; flex-shrink: 0;}
.mz .vf-op{font-family: sans-serif; font-size: 12px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 4px; width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center;}
.mz .ordenar-lista{display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px;}
.mz .ordenar-item{display: flex; align-items: center; gap: 10px;}
.mz .ordenar-caja{width: 26px; height: 26px; border: 2px solid var(--bosque); flex-shrink: 0; border-radius: 4px;}
.mz .ordenar-texto{font-size: 15px; font-weight: 600; line-height: 1.3;}
.mz .escribir-lineas{display: flex; flex-direction: column; gap: 6px; margin-bottom: 8px;}
.mz .escribir-linea{border-bottom: 1.5px solid var(--bosque); height: 22px; width: 100%;}
.mz .vf-texto{line-height: 1.725 !important;}
.mz .paso-item span{line-height: 1.725 !important;}
